import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Code Walkthrough: Overview of the Monitor 2020-06-24","description":"","frontmatter":{"title":"Ceph Code Walkthrough: Overview of the Monitor 2020-06-24","date":"2020-06-24T00:00:00.000Z","updated":"2020-06-25T00:00:00.000Z","tags":["Ceph","Monitor","Distributed Storage","CRUSH Algorithm","Election Mechanism","Paxos Algorithm"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Code_Walkthrough_-_Overview_of_the_Monitor_2020-06-24.md","filePath":"posts/2020/Ceph_Code_Walkthrough_-_Overview_of_the_Monitor_2020-06-24.md","lastUpdated":1780460162000}'),l={name:"posts/2020/Ceph_Code_Walkthrough_-_Overview_of_the_Monitor_2020-06-24.md"};function a(n,o,h,s,_,d){return t(),i("div",null,[...o[0]||(o[0]=[r('<p>Ceph Monitor代码架构与系统组件概述会议纪要：</p><h3 id="会议主题-ceph-monitor代码架构与系统组件概述" tabindex="-1">会议主题：Ceph Monitor代码架构与系统组件概述 <a class="header-anchor" href="#会议主题-ceph-monitor代码架构与系统组件概述" aria-label="Permalink to &quot;会议主题：Ceph Monitor代码架构与系统组件概述&quot;">​</a></h3><h3 id="参会人员-josh、greg等" tabindex="-1">参会人员：Josh、Greg等 <a class="header-anchor" href="#参会人员-josh、greg等" aria-label="Permalink to &quot;参会人员：Josh、Greg等&quot;">​</a></h3><h3 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h3><ol><li><p><strong>Ceph Monitor架构概述</strong></p><ul><li>Monitor代码位于<code>sourcetree</code>内部，主要文件包括<code>monitor.h</code>和<code>monitor.cc</code>。</li><li>Monitor是分布式系统，通过Elector和选举逻辑选举领导者，领导者负责排序更新请求，并授予PM租约。</li></ul></li><li><p><strong>选举机制</strong></p><ul><li>监视器通过Elector和选举逻辑进行领导者选举。</li><li>领导者负责管理更新排序和租约授予。</li></ul></li><li><p><strong>数据存储与消息处理</strong></p><ul><li>使用LevelDB作为数据存储，MonitorDBStore类进行封装。</li><li>基于MonitorMap的消息处理机制。</li></ul></li><li><p><strong>启动与初始化</strong></p><ul><li>Monitor启动流程包括解析标志、创建数据存储、设置消息传递机制等。</li><li>Bootstrap过程确保Monitor进入法定人数并保持最新状态。</li></ul></li><li><p><strong>消息与请求处理</strong></p><ul><li>Monitor处理多种消息类型，通过<code>handle_command</code>函数处理命令。</li><li>命令最终分发到特定的Monitor组件进行处理。</li></ul></li><li><p><strong>更新与提交</strong></p><ul><li>使用Paxos算法进行更新提议，一旦多数系统成员确认，更新即被提交。</li><li>定期提议更新以保持系统进度。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h3><ul><li>确认了Ceph Monitor的核心架构和关键组件。</li><li>明确了选举机制、数据存储、消息处理和更新提交的具体流程。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ul><li>继续优化和更新Monitor的收集系统。</li><li>深入研究特定Monitor组件的实现细节，如OSD Monitor。</li></ul><h3 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h3><p>感谢Greg的详细讲解，参会人员对Ceph Monitor的架构和运作有了更深入的理解。会议在提问环节结束后圆满结束。</p>',11)])])}const u=e(l,[["render",a]]);export{c as __pageData,u as default};
